var byLevel = new Dictionary<string,Dictionary<string,int>>();
int total = 0;
foreach (Element e in new FilteredElementCollector(doc).WhereElementIsNotElementType()) {
  if (e is View || e.Category == null) continue;
  total++;
  string lname = "(no level)";
  try { var lid = e.LevelId; if (lid != null && lid.IntegerValue > 0) { var l = doc.GetElement(lid) as Level; if (l != null) lname = l.Name; } } catch {}
  string c = e.Category.Name;
  if (!byLevel.ContainsKey(lname)) byLevel[lname] = new Dictionary<string,int>();
  if (!byLevel[lname].ContainsKey(c)) byLevel[lname][c] = 0;
  byLevel[lname][c]++;
}
var summary = byLevel.Select(kv => new { level = kv.Key, cats = kv.Value }).ToList();
return new { total = total, byLevel = summary };
